// **深**合并（嵌套对象不整个覆盖）
export function deepMerge(a, b) {
  const out = { ...a };
  for (const k of Object.keys(b)) {
    const av = out[k], bv = b[k];
    const bothObj = av && bv && typeof av === "object" && typeof bv === "object" && !Array.isArray(av) && !Array.isArray(bv);
    out[k] = bothObj ? deepMerge(av, bv) : bv;
  }
  return out;
}
